package kr.or.arte.seal.delivery.persistence;
import kr.or.arte.seal.delivery.application.*;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.*;
@Repository public class MyBatisMailOutboxRepository implements MailOutboxRepository{private final MailOutboxMapper mapper;public MyBatisMailOutboxRepository(MailOutboxMapper m){mapper=m;}public void insert(MailOutboxRecord r,UUID a,Instant n){mapper.insert(r,a,n);}public void cancelPending(UUID r,Instant n){mapper.cancelPending(r,n);}public List<MailOutboxRecord> claimDue(Instant n,int l,Instant lease){return mapper.claimDue(n,l,lease);}
 @Transactional public void accepted(UUID id,int a,Instant n){mapper.accepted(id,a,n);mapper.insertAttempt(id,a,"SMTP_ACCEPTED",null,n);}@Transactional public void retry(UUID id,int a,Instant next,String c,Instant n){mapper.retry(id,a,next,c,n);mapper.insertAttempt(id,a,"RETRY_SCHEDULED",c,n);}@Transactional public void failed(UUID id,int a,String c,Instant n){mapper.failed(id,a,c,n);mapper.insertAttempt(id,a,"SEND_FAILED",c,n);}public List<MailOutboxRecord> search(UUID a,MailOutboxStatus s){return mapper.search(a,s);}public Optional<MailOutboxRecord> findScoped(UUID a,UUID id){return mapper.findScoped(a,id);}public void requeue(UUID a,UUID id,Instant n){if(mapper.requeue(a,id,n)!=1)throw new IllegalStateException("재시도할 수 없는 메일입니다.");}}
